<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {X,Download} from 'lucide-vue-next'
import {downloadFile} from './api'
const props=defineProps<{record:Record<string,any>,canDownload?:boolean}>()
defineEmits<{close:[]}>()
const dialog=ref<HTMLDialogElement>(),error=ref(''),busy=ref(false)
async function download(){busy.value=true;error.value='';try{await downloadFile(`teaching/batches/${props.record.batch_id}/`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>dialog.value?.showModal())
</script>
<template><dialog ref="dialog" class="record-trace" @cancel="$emit('close')"><header><h2>本次提交的名单归属</h2><button class="icon-button" aria-label="关闭归属信息" @click="$emit('close')"><X :size="20"/></button></header><dl><dt>教师</dt><dd>{{record.teacher}} · 账号编号 {{record.teacher_id}}</dd><dt>班级</dt><dd>{{record.class_name||record.sheet}}<span v-if="record.roster_class_id"> · #{{record.roster_class_id}}</span></dd><dt>提交时属性</dt><dd>{{record.class_type}} · {{record.class_time}} · {{record.is_experimental===true?'实验班':record.is_experimental===false?'普通班':'旧记录未标注'}}</dd><dt>名单学期</dt><dd>{{record.class_snapshot?.year||record.year}} 年 {{record.class_snapshot?.term||record.term}}季</dd><dt>名单版本</dt><dd>{{record.roster_version||'历史记录未关联名单'}}</dd><dt>学生</dt><dd>{{record.student_name}} {{record.english_name}}</dd><dt>原件行</dt><dd>{{record.filename||`批次 ${record.batch_id}`}} · {{record.sheet}} 第{{record.source_row}}行</dd><dt v-if="record.class_snapshot?.course&&record.class_snapshot.course!==record.class_type">原课型</dt><dd v-if="record.class_snapshot?.course&&record.class_snapshot.course!==record.class_type">{{record.class_snapshot.course}}</dd></dl><p>以上为提交时的快照，后续改名、转班或归档不会修改这些归属。</p><footer><p v-if="error" role="alert" class="validation-summary">{{error}}</p><button v-if="canDownload" class="btn" :disabled="busy" @click="download"><Download :size="16"/>下载原件</button><button class="btn primary" @click="$emit('close')">关闭</button></footer></dialog></template>
<style scoped>.record-trace{width:min(620px,calc(100% - 24px));max-height:90dvh;border:1px solid #e2e8f1;border-radius:12px;padding:22px;box-shadow:0 20px 70px #17263a30}.record-trace::backdrop{background:#17263a55}.record-trace header,.record-trace footer{display:flex;justify-content:space-between;align-items:center;gap:12px}.record-trace dl{display:grid;grid-template-columns:100px 1fr;gap:16px;margin:24px 0;line-height:1.7}.record-trace dt{color:#667085}.record-trace dd{margin:0;overflow-wrap:anywhere}.record-trace small{display:block;color:#667085}.record-trace>p{color:#667085;font-size:14px;line-height:1.8}.record-trace footer{justify-content:flex-end;margin-top:24px;flex-wrap:wrap}.record-trace footer p{flex-basis:100%}</style>
